package main

import (
	"os"
	"path/filepath"
	"strings"
)

// withinRoot reports whether candidate resolves inside root, checked BOTH before
// and after symlink resolution — the TOCTOU guard (AC-4): no escaping path is
// ffprobed, read, or persisted. Replicated from
// plugins/base-scanner/pathguard.go (each plugin is its own package main).
// root must already be a resolved absolute path (resolveRoot); an unresolvable
// candidate (EvalSymlinks error) is rejected — skipping beats probing an
// unknown target.
func withinRoot(root, candidate string) bool {
	pre, err := filepath.Abs(filepath.Clean(candidate))
	if err != nil {
		return false
	}
	if !isUnder(root, pre) {
		return false
	}
	resolved, err := filepath.EvalSymlinks(pre)
	if err != nil {
		return false
	}
	return isUnder(root, resolved)
}

// isUnder reports whether path is root itself or a descendant of root; both
// inputs must be absolute. filepath.Rel keeps the comparison volume/anchor-aware
// — a different-tree path yields a ".."-prefixed rel (or an error) and is
// rejected.
func isUnder(root, path string) bool {
	rel, err := filepath.Rel(root, path)
	if err != nil {
		return false
	}
	if rel == "." {
		return true // path is exactly root
	}
	if rel == ".." {
		return false // path is the parent of root
	}
	if strings.HasPrefix(rel, ".."+string(os.PathSeparator)) {
		return false // path escapes above root
	}
	return true
}
